pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call: set pastBlockTime to some timestamp
        vm.warp(1000);
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        // Second call: same timestamp, 10 ether again
        // Reference: require(block.timestamp > pastBlockTime) will fail because 1000 > 1000 is false -> revert
        // Bug: require(block.timestamp >= pastBlockTime) will pass because 1000 >= 1000 is true
        vm.warp(1000);
        vm.deal(address(0x2), 10 ether);
        vm.prank(address(0x2));
        (bool success2,) = address(c).call{value: 10 ether}("");
        // Reference contract would have reverted, but we're testing the buggy version
        // So success2 should be true for bug (and false for reference)
        assertTrue(success2);
        // After the call, pastBlockTime should be 1000 (unchanged) for both,
        // but reference reverts so pastBlockTime stays at 1000 from first call,
        // while buggy version updates it to 1000 (same). Both are 1000, so state doesn't differ.
        // Actually the difference is in revert behavior: reference reverts, bug doesn't.
        // So assertion on success2 captures the divergence.
    }
}

