    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(c), 50 ether);
        vm.deal(address(this), 0 ether);
        // Compute a block where block.number % 15 == 0
        vm.roll(15);
        vm.warp(100);
        // First fallback: send 10 ether, will execute transfer/send
        vm.prank(address(0x1));
        (bool success1, ) = address(c).call{value: 10 ether}("");
        // Check that call succeeded
        // Second fallback in same block: should succeed in M (send fails silently) and revert in P (transfer reverts)
        vm.prank(address(0x2));
        (bool success2, ) = address(c).call{value: 10 ether}("");
        uint pastBlockTimeRef = c.pastBlockTime();
        // The reference's pastBlockTime is 100 (first call set it), M's pastBlockTime is 100 (first call) but second call overwrites it to 100 again (same value), but actually pastBlockTime won't change; however the assertion: In M, due to send failure, second call succeeds and sets pastBlockTime = 100 again, same value. But we need a difference. Let's re-evaluate.
        // Actually the difference: In P, second call reverts, so pastBlockTime stays 100. In M, second call succeeds, so pastBlockTime becomes 100 again, same value. They are equal. So this scenario does not trigger the difference correctly.
        // We must trigger a real block timestamp change between calls. Use different timestamps.
        // Redo: first call at block.time = 100, second at block.time = 200, but same block.number %15 ==0.
        vm.deal(address(c), 50 ether);
        vm.roll(15);
        vm.warp(100);
        vm.prank(address(0x1));
        address(c).call{value: 10 ether}("");
        // After first call, pastBlockTime = 100
        // Now second call: we cannot change block.timestamp in same block? Actually we can vm.warp again? vm.warp can be called multiple times, but block.timestamp increases. However block.number unchanged.
        vm.warp(200);
        vm.prank(address(0x2));
        (bool success2, ) = address(c).call{value: 10 ether}("");
        // In P: transfer reverts because block.number%15==0, so revert, pastBlockTime unchanged = 100
        // In M: send fails silently, so second call succeeds, pastBlockTime becomes 200
        assertTrue(pastBlockTime() == 100 ? c.pastBlockTime() == 100 : false);
    }
}

