import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 100 ether);
        vm.deal(address(c), 50 ether);
        vm.roll(15);
        vm.warp(100);

        // First fallback call - succeeds in both
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1);
        uint time1 = c.pastBlockTime();

        // Second fallback call in same block (block.number still 15)
        vm.warp(200);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        uint time2 = c.pastBlockTime();

        // In reference: second call reverts, so time2 == time1
        // In mutant: second call succeeds, so time2 > time1
        assertTrue(time2 == time1);
    }
}

