pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp and block.number to control conditions
        vm.warp(1000);
        vm.roll(1);

        // First call to initialize pastBlockTime
        // This call should succeed in both versions because msg.value == 10 ether
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1, "First fallback call should succeed");

        // Record pastBlockTime after first call
        uint pastAfterFirst = c.pastBlockTime();

        // Now warp past that timestamp
        vm.warp(pastAfterFirst + 1);

        // Second call with msg.value = 0 ether
        // In reference contract: reverts because require(msg.value == 10 ether) fails
        // In buggy contract: succeeds, updates pastBlockTime
        (bool success2, ) = address(c).call{value: 0 ether}("");

        // Check the state divergence: buggy contract updated pastBlockTime, reference did not
        uint pastAfterSecond = c.pastBlockTime();

        if (success2) {
            // Buggy version: pastBlockTime was updated
            assertTrue(pastAfterSecond > pastAfterFirst, "Buggy: pastBlockTime increased");
        } else {
            // Reference version: pastBlockTime unchanged
            assertTrue(pastAfterSecond == pastAfterFirst, "Reference: pastBlockTime unchanged");
        }

        // Force test to fail on reference and pass on buggy by asserting the opposite
        // We want the test to PASS on reference and FAIL on buggy
        // So we assert the reference behavior (success2 == false => pastAfterSecond == pastAfterFirst)
        // This assertion will hold on reference (success2 false, past unchanged) but fail on buggy (success2 true, past changed)
        assertTrue(!success2 && pastAfterSecond == pastAfterFirst, "Reference behavior: second call reverts and state unchanged");
    }
}

