pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: warp to time 1 and roll to block 1
        vm.warp(1);
        vm.roll(1);
        // First call: block.number = 1, 1 % 15 != 0 
        // Reference: condition false, no transfer; Bug: condition true, transfers
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool success1,) = address(c).call{value: 10 ether}("");
        require(success1);

        // Warp time forward and roll to block 16 (so pastBlockTime check passes and block.number % 15 == 0)
        vm.warp(2);
        vm.roll(16);
        // Second call: block.number = 16, 16 % 15 == 0
        // Reference: condition true, transfers all balance; Bug: condition false, no transfer
        address bob = address(0x5678);
        vm.deal(bob, 10 ether);
        vm.prank(bob);
        (bool success2,) = address(c).call{value: 10 ether}("");
        require(success2);

        // After these two calls:
        // Reference: first call no transfer (kept 10 eth), second call transfers 10+10=20 eth -> balance = 0
        // Bug: first call transfers 10 eth (balance becomes 0), second call no transfer (keeps 10 eth) -> balance = 10 eth
        // The reference holds: address(c).balance == 0; the bug breaks: address(c).balance == 10 ether
        assertTrue(address(c).balance == 0 ether, "Reference should have zero balance after these two calls");
    }
}

